package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation walked the input one byte at a time in a single
// loop, tracking header level, list state and a "saw a header" flag with
// intertwined special cases. It is rewritten here as a line-oriented parser:
// the input is split into lines and each line is classified as a header, a
// list item or paragraph text. All test expectations are unchanged.
//
// Line classification:
//
//   - a header is 1-6 '#' characters followed by a space, rendered as
//     <hN>text</hN>. Markdown defines only h1-h6, so a run of 7 or more '#'
//     is not a header and stays as paragraph text (e.g. "####### ...").
//   - a list item is a line starting with "* "; consecutive items are wrapped
//     in a single <ul>.
//   - anything else is paragraph text; the paragraph lines are wrapped in a
//     single <p>. The original implementation discarded newlines inside a
//     paragraph, so the lines are joined without a separator.
//
// Emphasis is resolved before the lines are parsed, mirroring the original
// implementation: the first pair of '__' becomes <strong> and the first pair
// of '_' becomes <em>.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var out strings.Builder
	inList := false
	var paragraph []string

	// flushParagraph writes the collected paragraph lines as a single <p> block.
	flushParagraph := func() {
		if len(paragraph) == 0 {
			return
		}
		out.WriteString("<p>" + strings.Join(paragraph, "") + "</p>")
		paragraph = nil
	}

	// closeList terminates the open <ul>, if any.
	closeList := func() {
		if inList {
			out.WriteString("</ul>")
			inList = false
		}
	}

	for _, line := range strings.Split(markdown, "\n") {
		if level, text, ok := parseHeader(line); ok {
			flushParagraph()
			closeList()
			fmt.Fprintf(&out, "<h%d>%s</h%d>", level, text, level)
			continue
		}
		if strings.HasPrefix(line, "* ") {
			flushParagraph()
			if !inList {
				out.WriteString("<ul>")
				inList = true
			}
			out.WriteString("<li>" + line[2:] + "</li>")
			continue
		}
		closeList()
		paragraph = append(paragraph, line)
	}

	flushParagraph()
	closeList()
	return out.String()
}

// parseHeader reports whether line is a markdown header. If it is, it returns
// the header level (1-6) and the header text (the line after the '#' run and
// the space). A run of 7 or more '#' characters, or a run not followed by a
// space, is not a header.
func parseHeader(line string) (level int, text string, ok bool) {
	level = 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 || level == len(line) || line[level] != ' ' {
		return 0, "", false
	}
	return level, line[level+1:], true
}

// applyEmphasis replaces the first pair of '__' with <strong> and the first
// pair of '_' with <em>, in that order (the '_' pass runs on the string left
// by the '__' pass, exactly as in the original implementation).
func applyEmphasis(markdown string) string {
	markdown = replaceFirstPair(markdown, "__", "<strong>", "</strong>")
	return replaceFirstPair(markdown, "_", "<em>", "</em>")
}

// replaceFirstPair replaces the first occurrence of marker with open and the
// next occurrence with close. If the markers do not form a pair, the string
// is returned unchanged.
func replaceFirstPair(s, marker, open, close string) string {
	start := strings.Index(s, marker)
	if start < 0 {
		return s
	}
	inner := s[start+len(marker):]
	end := strings.Index(inner, marker)
	if end < 0 {
		return s
	}
	return s[:start] + open + inner[:end] + close + inner[end+len(marker):]
}

